@ExtendWith(MockitoExtension.class) class GraduationServiceTest { @InjectMocks GraduationService service; @Mock GraduationApplicationMapper mapper; @Mock ServiceRelationMapper relationMapper; @Mock MediaAccountMapper accountMapper; @Mock AdminUserApi adminUserApi; @Mock DeptApi deptApi; @Mock BpmProcessInstanceApi processApi; @Mock MediaWorkflowEventService events;
 @Test void unavailableBpmRaisesStableFailure(){ServiceRelationDO relation=new ServiceRelationDO();relation.setId(1L);relation.setPersonId(2L);relation.setOwnerUserId(10L);relation.setStatus("active");when(relationMapper.selectById(1L)).thenReturn(relation);AdminUserRespDTO planner=new AdminUserRespDTO();planner.setDeptId(20L);when(adminUserApi.getUser(10L)).thenReturn(planner);DeptRespDTO dept=new DeptRespDTO();dept.setLeaderUserId(30L);when(deptApi.getDept(20L)).thenReturn(dept);AdminUserRespDTO supervisor=new AdminUserRespDTO();supervisor.setStatus(0);when(adminUserApi.getUser(30L)).thenReturn(supervisor);doAnswer(i->{i.getArgument(0,cn.iocoder.yudao.module.zsjos.dal.dataobject.studentops.GraduationApplicationDO.class).setId(9L);return 1;}).when(mapper).insert(any(cn.iocoder.yudao.module.zsjos.dal.dataobject.studentops.GraduationApplicationDO.class));when(processApi.createProcessInstance(eq(10L),any())).thenThrow(new RuntimeException("missing"));GraduationCreateReqVO req=new GraduationCreateReqVO();req.setServiceRelationId(1L);req.setReason("完成服务");req.setSnapshotJson("{}");assertThrows(RuntimeException.class,()->service.create(req,10L));verifyNoInteractions(events);}
}
